"""h(k) analysis: does the number of extra citations generated by one citation
depend on the reference-list length k of the citing work?

Estimator: binned additive Hawkes model with article, age and calendar-month
effects (auxiliary, biased), calibrated by indirect inference (ii.py).

Usage:  python analyze.py --data data --out results [--quick]
"""
from __future__ import annotations

import argparse
import json
import os
import time

import numpy as np
import pandas as pd

from hk_core import K_EDGES, LAGS, Panel, load_events, load_targets
from ii import Simulator, aux_diff, aux_fit, calibrate, invert, match_level, permute_k_within_target


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--data", default="data")
    ap.add_argument("--out", default="results")
    ap.add_argument("--M", type=int, default=120, help="months of follow-up")
    ap.add_argument("--end", default="2020-12", help="last calendar month used")
    ap.add_argument("--reps", type=int, default=4, help="simulations per grid point")
    ap.add_argument("--perms", type=int, default=5)
    ap.add_argument("--truth", type=float, default=None, help="true gamma (synthetic tests)")
    ap.add_argument("--quick", action="store_true")
    ap.add_argument("--no-variants", action="store_true")
    a = ap.parse_args()
    os.makedirs(a.out, exist_ok=True)
    t0 = time.time()
    log = lambda *s: print(f"[{(time.time() - t0) / 60:5.1f} min]", *s, flush=True)

    targets = load_targets(a.data)
    ev = load_events(a.data, targets)
    end_ym = int(a.end[:4]) * 12 + int(a.end[5:7]) - 1
    ns = ev[~ev["self"]].reset_index(drop=True)
    log(f"{len(targets)} targets, {len(ev)} citation events ({len(ns)} non-self), "
        f"{ev['j'].nunique()} citing works")
    num = dict(n_targets=len(targets), n_events=int(len(ev)), n_nonself=int(len(ns)),
               n_citing=int(ev["j"].nunique()), share_self=float(ev["self"].mean()),
               share_jan1=float(ns["jan1"].mean()), share_review=float((ns["type"] == "review").mean()),
               k_median=float(ns["k"].median()), k_quartiles=ns["k"].quantile([.25, .75]).tolist(),
               M=a.M, end=a.end, lags=LAGS, k_edges=list(K_EDGES), truth=a.truth)
    panel = Panel(targets, M=a.M, end_ym=end_ym)
    k0 = float(ns["k"].median())
    edges = K_EDGES

    # ---- auxiliary fit on the data ---------------------------------------
    prng = np.random.default_rng(7)
    A = aux_diff(panel, ns, edges, prng)
    num["panel_rows"] = int(len(A["y"]))
    num["aux"] = dict(D=float(A["stats"][0]), slope=A["slope"], perm_slopes=A["perm_slopes"],
                      level=float(A["stats"][1]), m=A["m"].tolist(),
                      kb=A["kb"].tolist(), n_events=A["nev"].tolist(), c=A["c"].tolist())
    s_ = A["H"].s
    log(f"aux on data: slope {A['slope']:.4f}, level {A['stats'][1]:.4f}; m_b = {np.round(A['m'], 3)}; "
        f"article scales s_i: median {np.median(s_):.2f}, 10-90% {np.round(np.quantile(s_, [.1, .9]), 2)}")

    # ---- indirect inference ----------------------------------------------
    sim = Simulator(targets, ns, panel, A, k0, end_ym, seed=20261024, log=log)
    grid = (0.0, 0.25, 0.5) if a.quick else (-0.25, 0.0, 0.25, 0.5, 0.75, 1.0)
    tab = calibrate(sim, panel, edges, A["stats"], grid=grid, reps=2 if a.quick else a.reps, log=log)
    g_hat, g_se, ok = invert(tab, A["stats"][0])
    log(f"gamma_hat = {g_hat:.3f} ± {g_se:.3f} (bracketed: {ok})")

    # model check at gamma_hat
    kap, fits = match_level(sim, panel, edges, g_hat, A["stats"][1], reps=3 if not a.quick else 1, log=log)
    m_sim = np.array([f["m"] for f in fits])
    num["ii"] = dict(gamma=g_hat, se=g_se, bracketed=ok, k0=k0, table=tab.to_dict(orient="list"),
                     kappa=kap, m_sim_mean=m_sim.mean(0).tolist(), m_sim_sd=m_sim.std(0, ddof=1).tolist(),
                     D_sim=[float(f["stats"][0]) for f in fits])

    # ---- placebo: the whole procedure on data with k shuffled within article
    rng = np.random.default_rng(1)
    perm = []
    for p in range(1 if a.quick else a.perms):
        Ap = aux_diff(panel, permute_k_within_target(ns, rng), edges, rng)  # slope with k shuffled
        D = Ap["stats"][0] * A["stats"][1] / Ap["stats"][1]
        perm.append(dict(D=float(Ap["stats"][0]), level=float(Ap["stats"][1]), gamma=invert(tab, D)[0]))
    num["permutation"] = perm
    log(f"placebo (k shuffled within article): slope = {[round(p['D'], 4) for p in perm]}, "
        f"gamma = {[round(p['gamma'], 3) for p in perm]}")

    # ---- variants (data side; mapped through the main binding function) ---
    variants = {}
    nj = ns[~ns["jan1"]]
    variants["drop Jan-1 dated citations"] = nj
    variants["citing reviews removed"] = ns[ns["type"] != "review"]
    kr = ns.dropna(subset=["k_rel"]).copy()
    kr["k"] = np.maximum(kr["k_rel"].values * k0, 1.0)
    variants["k relative to field-year median"] = kr
    variants["self-citations included"] = ev.reset_index(drop=True)
    early = targets["P"] < targets["P"].median()
    variants["articles published in first half"] = ns[early.values[ns["i"].values]]
    vres = {}
    for name, e in ({} if a.no_variants else variants).items():
        Av = aux_diff(panel, e.reset_index(drop=True), edges, rng)
        D = Av["stats"][0] * A["stats"][1] / Av["stats"][1]
        g, _, okv = invert(tab, D)
        vres[name] = dict(D=float(Av["stats"][0]), slope=Av["slope"], level=float(Av["stats"][1]), gamma=g,
                          bracketed=okv, m=Av["m"].tolist(), kb=Av["kb"].tolist())
        log(f"variant {name}: slope = {Av['stats'][0]:.4f}, gamma ≈ {g:.3f}")
    num["variants"] = vres
    num["runtime_min"] = (time.time() - t0) / 60
    json.dump(num, open(os.path.join(a.out, "numbers.json"), "w"), indent=1, default=float)
    tab.to_csv(os.path.join(a.out, "binding.csv"), index=False)
    log("done")


if __name__ == "__main__":
    main()
